"""High-priority, question-specific answer-art handoff for the reviewed 1405 app."""
from pathlib import Path
from PIL import Image
import base64, html, io, json, re
import fitz

ROOT=Path(__file__).resolve().parents[1];A=ROOT/'app/src/main/assets';OUT=ROOT/'review'
Q={q['canonicalId']:q for ch in range(10,16) for q in json.loads((A/f'content/chapter{ch}.json').read_text())}
S={}
def add(ch,n,title,spec,reuse=()):
    cid=f'g7_ch{ch:02}_{n if isinstance(n,str) else "q"+str(n).zfill(2)}';assert cid in Q
    S[cid]=dict(title=title,spec=spec,reuseFor=list(reuse))

add(11,3,'مقایسهٔ یاختهٔ عصبی، ماهیچه‌ای و خونی','سه گروه به ترتیبِ راست به چپِ شکل سؤال: عصبی، ماهیچه‌ای دوکی و یاخته‌های خونی. امتدادهای یاختهٔ عصبی و دوکی بودن نمونهٔ ماهیچه‌ای مشخص شود. در گروه خون، گویچهٔ قرمز بالغ انسان بدون هسته و گویچهٔ سفید با هسته رسم شود. غشا و میان‌یاخته بخش مشترک‌اند؛ برای همهٔ یاخته‌های خون هسته نکشید. عنوان «هر ماهیچه‌ای دوکی است» نوشته نشود؛ نمونهٔ همین سؤال معیار است.')
add(11,4,'غشای یاخته و عبور انتخابی','مقطع دو لایهٔ فسفولیپیدی، پروتئین گذرگاهی و زنجیرهٔ قندی در سطح بیرونی؛ داخل و خارج یاخته معلوم باشد. ورود و خروج چند نوع ماده با پیکان جدا و سد شدن یک نوعِ نامتناسب نمایش داده شود. غشا «فقط دروازهٔ مواد مفید» نیست و مادهٔ مضر نیز ممکن است عبور کند؛ انتخاب‌پذیری را به ویژگی ماده و مسیر عبور مربوط کنید. نام‌های لیپید، پروتئین و کربوهیدرات کوتاه و خوانا باشند.')
add(11,6,'نقشهٔ اندامک‌های یاخته و وظیفهٔ آن‌ها','همان شماره‌گذاری تصویر سؤال، با هشت برچسب: ۱ راکیزه/میتوکندری، ۲ گلژی، ۳ شبکهٔ آندوپلاسمی، ۴ هسته، ۵ کریچه/واکوئل، ۶ رناتن/ریبوزوم، ۷ میان‌یاخته/سیتوپلاسم، ۸ غشای یاخته. نوک خط هر شماره دقیقاً به ساختار مربوط برسد. وظیفه‌ها در کادر مستقل: تبدیل انرژی مواد غذایی به شکل قابل استفاده، بسته‌بندی، حمل درون‌یاخته‌ای، تنظیم، ذخیره، پروتئین‌سازی، محیط اندامک‌ها و تنظیم عبور مواد. میتوکندری انرژی را از هیچ تولید نکند.')
add(11,7,'مقایسهٔ یاختهٔ گیاهی و جانوری','نسخهٔ پاسخ‌دار شکل سؤال: ۱ سبزدیسه، ۲ راکیزه، ۳ واکوئل مرکزی، ۴ غشای یاخته، ۵ دیوارهٔ یاخته. غشای زیر دیواره جدا و قابل تشخیص باشد. در هر دو، غشا و میتوکندری دیده شوند؛ در نمونهٔ گیاهیِ دارای سبزدیسه، دیواره و واکوئل مرکزی بزرگ رسم شوند. نگویید همهٔ یاخته‌های گیاه کلروپلاست دارند؛ مثلاً یاختهٔ ریشه معمولاً ندارد. شماره‌ها، محل خطوط و سمت دو نمونه عوض نشوند.')
add(12,4,'آزمون نشاسته در سه خوراکی','سه نمونهٔ هم‌اندازه از نان، سیب‌زمینی و خیار پوست‌کنده با مقدار یکسان لوگول، همراه وضعیت پیش و پس از افزودن معرف. نان و سیب‌زمینی آبی تیره/آبی‌سیاه؛ خیار در شرایط این آزمایش این تغییر را ندارد. هر سه نمونهٔ صورت سؤال نمایش داده شوند؛ نان در توضیح چاپی پاسخ از قلم افتاده است. تغییر رنگِ نمونه و معرف ملاک باشد و کل ظرف بی‌دلیل آبی نشود.')
add(12,6,'آزمون لکهٔ چربی با گردو و آب سبزی','دو ناحیه روی کاغذ یکسان: مغز گردو و آب سبزی. دو زمان «بلافاصله» و «پس از خشک‌شدن آب» جدا شوند. لکهٔ نیمه‌شفافِ ماندگار در ناحیهٔ گردو باقی بماند؛ خیس‌شدن موقت کاغذِ آب سبزی پس از تبخیر از بین برود. هر لکهٔ خیس نشانهٔ چربی معرفی نشود و دربارهٔ صفر بودن مطلق چربی همهٔ سبزی‌ها ادعا نشود.')
add(12,18,'خواندن نمودار خوراکیِ پرقند و پرچربی','بازطراحی همان نمودار سؤال ۱۸ با نام، ارتفاع، عدد، واحد و مقیاس دقیقِ منبع؛ هیچ عددی از حافظه یا حدس اضافه نشود. قند و چربیِ بیشتر نسبت به پروتئین برجسته و نتیجهٔ «نقش غالب: تأمین انرژی؛ نمونهٔ سازگار: کیک خامه‌ای» در کادر پاسخ نوشته شود. با نمودار سؤال ۱۹ ادغام یا جابه‌جا نشود.')
add(12,19,'خواندن نمودار خوراکیِ پرپروتئین','همان نمودار سؤال ۱۹ با تمام داده‌ها و واحدهای اصلی؛ ستون پروتئین برجسته شود. پاسخ «ساخت و ترمیم بافت‌ها؛ نمونهٔ سازگار: کباب» در کادر جدا باشد. نگویید این خوراکی هیچ انرژی ندارد؛ تأکید سؤال بر نقش غالب پروتئین است. عددها با نمودار سؤال ۱۸ تعویض نشوند.')
add(13,2,'دستگاه گوارش انسان با نام و کار اندام‌ها','نسخهٔ کامل و پاسخ‌دار شکل: ۱ مری، ۲ معده، ۳ باریک‌روده، ۴ کبد، ۵ فراخ‌روده. کنار شکل، B لوزالمعده، C مری، D باریک‌روده، E معده، F کبد و G فراخ‌روده بیاید. کبد، کیسهٔ صفرا و لوزالمعده از مسیر عبور مستقیم غذا جدا باشند. در جذب، بعضی چربی‌ها ابتدا به لنف می‌روند؛ همهٔ جذب به‌صورت مستقیم به خون رسم نشود. صفرا آنزیم نیست و غذا از داخل کبد عبور نمی‌کند.')
add(13,3,'مقایسهٔ گوارش پرندهٔ شکل با انسان','دو مسیر موازی، با چینه‌دان برای ذخیره و سنگدان برای خردکردن در پرندهٔ همین سؤال. انسان این دو اندام را ندارد. رودهٔ باریک و بزرگ پرنده نیز نشان داده شوند؛ عبارت اشتباهِ «پرنده فقط یک روده دارد» یا «پرنده رودهٔ باریک و بزرگ ندارد» در تصویر نیاید. وجود چینه‌دان به همهٔ گونه‌های پرنده تعمیم داده نشود؛ شکل، مدل همین پرنده است.')
add(13,5,'ساختمان دندان و آغاز پوسیدگی','مقطع تاج و ریشه؛ برچسب‌های سؤال از بیرون به درون: مینا، عاج و مغز دندان. مینا فقط روی تاج و مغز شامل عصب و رگ باشد. سه قاب علت: باقی‌ماندهٔ قند، فعالیت باکتری و تولید اسید، آسیب به مینای سطحی. پوسیدگی از مغز شروع نشود و قند بدون نقش باکتری مستقیماً اسید نامیده نشود. دندان پیش/نیش/آسیا در این تصویر با لایه‌های دندان اشتباه نشوند.')
add(13,6,'چین و پرزِ باریک‌روده و افزایش سطح جذب','نمای دیوارهٔ روده، بزرگ‌نمایی یک پرز و مسیر مواد به مویرگ خون و رگ لنفی. سلسلهٔ بزرگ‌نمایی مقیاس آموزشی داشته باشد. چین، پرز و یاخته جدا باشند؛ پیکان جذب از فضای روده به درون پرز برود. قندهای ساده و آمینواسیدها به خون و بخش عمدهٔ چربی‌های جذب‌شده ابتدا به لنف نشان داده شوند. نتیجهٔ کوتاه: افزایش سطح تماس و جذب؛ نه تبدیل خود غذا به خون.')
add(13,8,'معده، لوزالمعده، کبد و کیسهٔ صفرا','همان زاویه و شماره‌های منبع: ۱ معده، ۲ لوزالمعده، ۳ کبد، ۴ کیسهٔ صفرا. کیسهٔ صفرا کوچک و زیر کبد، لوزالمعده مجاور/پشت معده و ابتدای باریک‌روده با مسیر درست مجراها رسم شود. صفرا در کبد ساخته و در کیسه ذخیره می‌شود؛ مسیر ترشحات به ابتدای باریک‌روده برسد، نه به داخل مری.',reuse=('g7_ch13_q09',))
add(13,'mcq01','بسته‌شدن مسیرهای تنفسی هنگام بلع','دو حالتِ جدا: تنفس عادی و بلع. در بلع، راه غذا به مری باز؛ کام نرم و زبان کوچک راه بینی را می‌بندند و برچاکنای از ورودی راه هوایی محافظت می‌کند. شماره‌های جای خالی: ۱ مری، ۲ بینی، ۳ نای؛ پاسخ متن سؤال ب است. نای و مری جابه‌جا نشوند. پیکان غذا وارد نای نشود و بالا آمدن کام نرم با حرکت اپی‌گلوت یک قطعهٔ مشترک معرفی نشود.')
add(13,'mcq03','کار علمی سه نوع دندان؛ مستقل از کلیدِ در انتظار تأیید','سه نمونهٔ دندان با نام و شکل درست: آسیا با سطح پهن برای جویدن و خردکردن؛ پیش با لبهٔ برنده برای بریدن؛ نیش با نوک تیز برای پاره‌کردن. فقط تطبیق علمی رسم شود. حرف گزینه روی تصویر نوشته نشود؛ کلید چاپی «ج» همچنان در انتظار تصمیم مؤلف است و برنامه آن را جدا حفظ می‌کند. ترتیب علمی نقش‌ها: آسیا، پیش، نیش؛ ترتیب اشتباه کلید در تصویر تکرار نشود.')
add(14,2,'ساختمان قلب و نام حفره‌ها و رگ‌ها','نسخهٔ پاسخ‌دار و خوانای همان شکل؛ شمارهٔ حفره‌ها عین منبع بماند، دو بالایی دهلیز و دو پایینی بطن. راست و چپ تشریحی بیمار از سمت صفحه جدا و با راهنمای واضح مشخص شوند؛ بطن چپ ضخیم‌تر باشد. آئورت از بطن چپ، سرخرگ ششی از بطن راست، سیاهرگ‌های ششی به دهلیز چپ و سیاهرگ‌های بزرگ به دهلیز راست وصل شوند. رگ‌های تاجی روی سطح قلب مستقل از مسیر ششی نشان داده شوند.')
add(14,4,'مسیر پیوستهٔ گردش ششی و عمومی','یک مسیر بستهٔ ساده و بدون تقاطع گمراه‌کننده: سیاهرگ‌های بدن → دهلیز راست → بطن راست → سرخرگ ششی → مویرگ شش → سیاهرگ ششی → دهلیز چپ → بطن چپ → آئورت → مویرگ‌های بدن → سیاهرگ‌های بدن. پیکان‌ها یکنواخت و برچسب‌های همهٔ بخش‌ها باشند. آبی و قرمز فقط قرارداد کم‌اکسیژن‌تر/پراُکسیژن‌ترند؛ خون کم‌اکسیژن واقعاً آبی نیست. ارتباط فیزیولوژیک درست را فدای چیدمان افقی نکنید.',reuse=('g7_ch14_q05',))
add(14,6,'سه مرحلهٔ چرخهٔ قلب','سه قاب با دهلیزها و بطن‌های یکسان: انقباض دهلیز، انقباض بطن، استراحت عمومی. جهت عبور خون و باز/بسته بودن دریچه‌های مناسب هر قاب مشخص باشد. در استراحت، پرشدن منفعل بطن‌ها هم نشان داده شود. خون‌گیری دهلیز را فقط به یک لحظهٔ استراحت محدود نکنید و انقباض دهلیز، منبع تمام پرشدن بطن معرفی نشود. مدت یا فشار عددی حدسی نگذارید.')
add(14,7,'مقایسهٔ ساختمان سه نوع رگ','سرخرگ، سیاهرگ و مویرگ با مقطع و جهت جریان: سرخرگ از قلب، سیاهرگ به قلب، مویرگ محل تبادل. سرخرگ دیوارهٔ ماهیچه‌ای/کشسان ضخیم‌تر؛ سیاهرگ نازک‌تر و نمونهٔ دارای دریچه؛ مویرگ دیوارهٔ بسیار نازکِ یک‌لایهٔ پوششی. نام رگ بر پایهٔ جهت نسبت به قلب باشد، نه اکسیژن؛ در راهنما استثنای رگ ششی روشن شود. همهٔ سیاهرگ‌ها دارای دریچه فرض نشوند.')
add(14,9,'اجزای خون و کار گویچه‌ها و پلاکت','دو بخش: ۱ نمونهٔ جداشدهٔ خون با حدود ۵۵٪ خوناب و حدود ۴۵٪ اجزای خونی، با لایهٔ بسیار نازک گویچهٔ سفید/پلاکت در جای درست؛ ۲ بزرگ‌نمایی گویچهٔ قرمز بالغ انسان بدون هسته و دوطرف‌فرورفته، گویچهٔ سفید هسته‌دار و پلاکت به‌صورت قطعهٔ کوچک یاخته‌ای. نقش‌ها حمل گاز، دفاع و انعقاد. مقدار حدود ۵ لیتر فقط برای بزرگسالِ نمونه است؛ نسبت‌ها دقیق و ثابت برای همهٔ افراد معرفی نشوند.',reuse=('g7_ch14_q10',))
add(15,2,'مسیر هوا تا کیسه‌های هوایی','نسخهٔ پاسخ‌دار سؤال: ۱ بینی، ۲ حلق، ۳ حنجره، ۴ نای، ۵ نایژه، ۶ نایژک‌ها. یک کیسهٔ هوایی در بزرگ‌نمایی انتهای شاخه‌ها، با مویرگ و برچسب‌ها نشان داده شود. مسیر هوا از ورودی تا حلق، حنجره، نای، نایژه و نایژک یکپارچه باشد؛ مری جزو مسیر تنفس نشود. متن کامل جای خالی‌ها در برنامه می‌ماند؛ شکل، شمارهٔ اصلی را عوض نکند.')
add(15,4,'نقش دیافراگم در دم و بازدم','دو قاب هم‌اندازه: دم، دیافراگم منقبض و پایین‌تر/تخت‌تر، حجم قفسهٔ سینه بیشتر و پیکان ورود هوا؛ بازدم عادی، دیافراگم شل و گنبدی‌تر/بالاتر، کاهش حجم و خروج هوا. دیافراگم زیر شش‌ها و مرز سینه و شکم باشد. بالا رفتن دیافراگم در دم رسم نشود. فشار را فقط به صورت نسبی نشان دهید؛ عدد حدسی لازم نیست.')
add(15,8,'تبادل گاز کنار شش و کنار بافت','دو بزرگ‌نمایی با رنگ و راهنمای ثابت: در شش، O₂ از کیسهٔ هوایی به خون و CO₂ از خون به کیسه؛ در بافت، O₂ از خون به یاخته و CO₂ از یاخته به خون. هر چهار پیکان سر واضح و نام گاز داشته باشند. در راهنمای رنگ خون، قرمز تیره را به جای خون آبی واقعی توضیح دهید. تنفس یاخته‌ای با تبادل گازِ شش یک مرحله معرفی نشود.')
add(15,9,'آزمون کربن‌دی‌اکسید بازدم با آب آهک','سه قابِ ساده: آب آهک شفاف، دمیدن آرام بازدم با نی، کدر شدن ناشی از تشکیل رسوب. نی زیر سطح مایع برای خروج حباب‌ها باشد و پیکان فقط از دهان به مایع برود. مکیدن یا ورود آب آهک به دهان نمایش داده نشود؛ عنوان آزمایش کلاسی زیر نظر دبیر باشد. فقط ایجاد حباب، مدرک شناسایی CO₂ نیست؛ شفافیت پیش و پس از بازدم مقایسه شود.')
add(15,10,'دستگاه ادراری و تفاوت خون با ادرار','همان شماره‌ها: ۱ کلیه، ۲ میزنای، ۳ مثانه. دو کلیه در دو طرف ستون مهره‌ها، میزنای از کلیه به مثانه و مجرای خروج از مثانه جدا باشد. سرخرگِ ورودی و سیاهرگِ خروجیِ کلیه با پیکان مشخص شوند؛ رگ‌ها به مثانه راه نداشته باشند. مسیر خون و مسیر ادرار در شکل جدا و نام‌گذاری میزنای با پیشابراه اشتباه نشود.')
add(15,12,'برش کلیه و مسیر ساخته‌شدن و دفع ادرار','نسخهٔ پاسخ‌دار شکل: ۱ هرم، ۲ لگنچه، ۳ میزنای. بزرگ‌نمایی یک گردیزه در محل تشریحی مناسب، ارتباط با مویرگ خون و سپس مسیر گردیزه‌ها/لوله‌های جمع‌کننده → لگنچه → میزنای → مثانه نمایش داده شود. خون مستقیماً درون لگنچه نریزد؛ گردیزه فقط صافی‌ای که همهٔ مواد را دفع می‌کند معرفی نشود و بازجذب آب و مواد لازم به خون با پیکان مستقلِ ساده معلوم باشد.')

def thumb(question):
    figures=[b['asset'] for b in question['nativeQuestion'] if b['type']=='figure']
    if not figures:return ''
    asset=figures[0]
    if asset.startswith('pdf:'):
        file,region=asset[4:].split('#');pn,*bounds=map(float,region.split('|')[0].split(','))
        doc=fitz.open(A/'source'/file);pix=doc[int(pn)-1].get_pixmap(matrix=fitz.Matrix(1.6,1.6),clip=fitz.Rect(bounds),alpha=False)
        im=Image.open(io.BytesIO(pix.tobytes('png'))).convert('RGB')
    elif asset.startswith('crop:'):
        file,rect=asset[5:].split('#');im=Image.open(A/'images'/file).convert('RGB').crop(tuple(map(int,rect.split(','))))
    else:im=Image.open(A/'images'/asset).convert('RGB')
    im.thumbnail((650,430));buf=io.BytesIO();im.save(buf,'WEBP',quality=88,method=4)
    return 'data:image/webp;base64,'+base64.b64encode(buf.getvalue()).decode()

def plain(blocks):
    out=[]
    for b in blocks:
        if b['type'] in ('text','cloze'):out.append(re.sub(r'\{\{[^}]+}}','……',b['text']))
        elif b['type']=='table':out.append('\n'.join(' | '.join(row) for row in [b['headers']]+b['rows']))
        elif b['type']=='math':out.append(' '.join(p.get('text') or p.get('numerator','')+'/'+p.get('denominator','') for p in b['parts']))
    return '\n'.join(out)

